import java.util.Scanner;

public class ShowRoom
{
    String name;     // name of the customer
    long mobno;      // mobile number of the customer
    double cost;     // cost of the items purchased
    double dis;      // discount amount
    double amount;   // amount to be paid after discount

    ShowRoom()
    {
        name = "";
        mobno = 0L;
        cost = 0.0;
        dis = 0.0;
        amount = 0.0;
    }

    void input()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter customer name: ");
        name = sc.nextLine();
        System.out.print("Enter mobile number: ");
        mobno = sc.nextLong();
        System.out.print("Enter cost of items purchased: ");
        cost = sc.nextDouble();
    }

    void calculate()
    {
        if (cost <= 10000)
            dis = cost * 5 / 100;
        else if (cost <= 20000)
            dis = cost * 10 / 100;
        else if (cost <= 35000)
            dis = cost * 15 / 100;
        else
            dis = cost * 20 / 100;
        amount = cost - dis;
    }

    void display()
    {
        System.out.println("Customer name: " + name);
        System.out.println("Mobile number: " + mobno);
        System.out.println("Amount to be paid: " + amount);
    }

    public static void main(String args[])
    {
        ShowRoom ob = new ShowRoom();
        ob.input();
        ob.calculate();
        ob.display();
    }
}

Sample run: cost = 25000 falls in the 15% slab, so dis = 3750.0 and amount = 21250.0.

