import java.util.Scanner;

public class Menu
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.println("1. Letters A to Z with their Unicode");
        System.out.println("2. Number pattern");
        System.out.print("Enter your choice: ");
        int ch = sc.nextInt();   // user's menu choice
        switch (ch)
        {
            case 1:
                System.out.println("Letters\tUnicode");
                for (char c = 'A'; c <= 'Z'; c++)
                    System.out.println(c + "\t" + (int) c);
                break;
            case 2:
                for (int i = 1; i <= 5; i++)        // row number
                {
                    for (int j = 1; j <= i; j++)    // numbers in the row
                        System.out.print(j + " ");
                    System.out.println();
                }
                break;
            default:
                System.out.println("Invalid choice");
        }
    }
}

Choice 1 prints A 65, B 66, ... Z 90; choice 2 prints the five-row triangle 1 / 1 2 / ... / 1 2 3 4 5.

