import java.util.Scanner;

public class BubbleSort
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int a[] = new int[15];   // array of 15 integers
        System.out.println("Enter 15 integers:");
        for (int i = 0; i < 15; i++)
            a[i] = sc.nextInt();

        for (int i = 0; i < 14; i++)            // passes
        {
            for (int j = 0; j < 14 - i; j++)    // compare adjacent elements
            {
                if (a[j] > a[j + 1])
                {
                    int t = a[j];
                    a[j] = a[j + 1];
                    a[j + 1] = t;
                }
            }
        }

        System.out.println("Sorted array in ascending order:");
        for (int i = 0; i < 15; i++)
            System.out.print(a[i] + " ");
        System.out.println();
    }
}

Each pass compares adjacent elements and swaps them when the left one is larger, so the largest remaining value bubbles to the end; after 14 passes the array is in ascending order.

