public class Overload
{
    // (a) sum of x^1 + x^2 + ... + x^n
    void series(int x, int n)
    {
        double sum = 0;
        for (int i = 1; i <= n; i++)
            sum += Math.pow(x, i);
        System.out.println("Sum = " + sum);
    }

    // (b) 0, 7, 26, 63 ... p terms (term = i^3 - 1)
    void series(int p)
    {
        for (int i = 1; i <= p; i++)
            System.out.print((i * i * i - 1) + " ");
        System.out.println();
    }

    // (c) sum of 1/2 + 1/3 + ... + 1/10
    void series()
    {
        double sum = 0.0;
        for (int i = 2; i <= 10; i++)
            sum += 1.0 / i;
        System.out.println("Sum = " + sum);
    }

    public static void main(String args[])
    {
        Overload ob = new Overload();
        ob.series(2, 5);
        ob.series(5);
        ob.series();
    }
}

Check: series(2,5) gives 2+4+8+16+32 = 62.0; series(5) prints 0 7 26 63 124 (each term is i³ − 1); series() gives 1/2 + 1/3 + ... + 1/10 ≈ 1.9290.

