import java.util.Scanner;

public class CountA
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence:");
        String s = sc.nextLine();
        s = " " + s.toUpperCase();   // leading space so the first word is counted too
        int count = 0;                // words starting with 'A'
        for (int i = 0; i < s.length() - 1; i++)
        {
            if (s.charAt(i) == ' ' && s.charAt(i + 1) == 'A')
                count++;
        }
        System.out.println("Total number of words starting with letter 'A' = " + count);
    }
}

Trace on the sample: the words ADVANCEMENT, AND, APPLICATION and ARE start with 'A', so the program prints: Total number of words starting with letter 'A' = 4

